  @TemplateID = @TemplateID_cf3ba0b85409,
  @TypeID = @TypeID_cf3ba0b85409,
  @TemplateText = @TemplateText_cf3ba0b85409,
  @Priority = @Priority_cf3ba0b85409,
  @IsActive = @IsActive_cf3ba0b85409
END ELSE
BEGIN
EXEC [${flyway:defaultSchema}].spUpdateTemplateContent @ID = @ID_cf3ba0b85409,
  @TemplateID = @TemplateID_cf3ba0b85409,
  @TypeID = @TypeID_cf3ba0b85409,
