@TemplateID_19ddab9875a7 UNIQUEIDENTIFIER,
@TypeID_19ddab9875a7 UNIQUEIDENTIFIER,
@TemplateText_19ddab9875a7 NVARCHAR(MAX),
@Priority_19ddab9875a7 INT,
@IsActive_19ddab9875a7 BIT
SET
  @ID_19ddab9875a7 = '726b0a99-ca6a-410a-bf6d-34d15f33ebb8'
