  @TemplateID = @TemplateID_573e3ac6f5a7,
  @TypeID = @TypeID_573e3ac6f5a7,
  @TemplateText = @TemplateText_573e3ac6f5a7,
  @Priority = @Priority_573e3ac6f5a7,
  @IsActive = @IsActive_573e3ac6f5a7
END ELSE
BEGIN
