SET
  @ID_f579a47d402f = 'FACEE516-41BD-4346-BB6F-07F44CF97E2F'
SET
  @Name_f579a47d402f = N'Discard Work Queue Delivery'
SET
  @OperationKey_f579a47d402f = N'WorkQueue.DiscardDelivery'
SET
  @CategoryID_f579a47d402f = '826B85CB-BE74-4716-94A3-1126DBED59AD'
SET
  @Description_f579a47d402f = N'Resolves one delivery without processing it, with a required reason. A pending or dead-lettered delivery becomes Discarded immediately; discarding a dead-lettered Ordered head unblocks its key. An in-flight delivery is cancelled instead (cancelRequested = true): the running handler is told to stop within one heartbeat interval (30 s at most) and the delivery becomes Discarded as soon as the handler acknowledges, or at lease expiry if its worker is gone. Implemented by WorkQueueDiscardDeliveryServerOperation in @memberjunction/work-queue-engine.'
SET
  @InputTypeName_f579a47d402f = N'WorkQueueDiscardDeliveryInput'
SET
  @InputTypeDefinition_f579a47d402f = N'/** Input for `WorkQueue.DiscardDelivery`. */
export interface WorkQueueDiscardDeliveryInput {
    subscriptionName: string;
    /** A pending, dead-lettered or in-flight delivery. */
    deliveryID: string;
    /** Why the work is being dropped. Required; at most 1000 characters. */
    reason: string;
}
'
SET
  @InputTypeIsArray_f579a47d402f = 0
SET
  @OutputTypeName_f579a47d402f = N'WorkQueueDiscardDeliveryOutput'
SET
  @OutputTypeDefinition_f579a47d402f = N'/** Output of `WorkQueue.DiscardDelivery`. */
export interface WorkQueueDiscardDeliveryOutput {
    /** False when the transport cannot discard this kind of delivery (for example any SQS message). */
    supported: boolean;
    /** True when the delivery is now Discarded, or (for an in-flight delivery) its cancel was recorded. */
    discarded: boolean;
    /**
     * True when the delivery was in flight: CancelRequestedAt is set, the running handler''s next heartbeat (30 s at
     * most) aborts it with reason ''Cancelled'', and the row becomes Discarded when the handler acknowledges — or at
     * lease expiry if its worker is gone (03 §7).
     */
    cancelRequested: boolean;
}
'
SET
  @OutputTypeIsArray_f579a47d402f = 0
SET
  @ExecutionMode_f579a47d402f = N'Sync'
SET
  @RequiredScope_f579a47d402f = N'workqueue:operate'
SET
  @RequiresSystemUser_f579a47d402f = 0
SET
  @GenerationType_f579a47d402f = N'Manual'
