  @ID_3896f90effd3 = '6CE1A749-455A-4315-B3DA-44F56D1834C0'
SET
  @Name_3896f90effd3 = N'Get Work Queue Backlog'
SET
  @OperationKey_3896f90effd3 = N'WorkQueue.GetBacklog'
SET
  @CategoryID_3896f90effd3 = '826B85CB-BE74-4716-94A3-1126DBED59AD'
SET
  @Description_3896f90effd3 = N'Returns the autoscaler metric for one subscription: claimable pending deliveries (partition rules applied) plus in-flight deliveries. Both counts matter — schedulers such as KEDA subtract running executions from the metric, so a pending-only count starves the queue. Each count is capped at 1000 (capped = true). Implemented by WorkQueueGetBacklogServerOperation in @memberjunction/work-queue-engine.'
SET
  @InputTypeName_3896f90effd3 = N'WorkQueueGetBacklogInput'
SET
  @InputTypeDefinition_3896f90effd3 = N'/** Input for `WorkQueue.GetBacklog`. */
export interface WorkQueueGetBacklogInput {
    subscriptionName: string;
}
'
SET
  @InputTypeIsArray_3896f90effd3 = 0
SET
  @OutputTypeName_3896f90effd3 = N'WorkQueueGetBacklogOutput'
SET
  @OutputTypeDefinition_3896f90effd3 = N'/** Output of `WorkQueue.GetBacklog` — the autoscaler metric for one subscription. */
export interface WorkQueueGetBacklogOutput {
    /** False when the subscription''s transport cannot report a backlog (AWS — scale Lambda from the queue''s own metrics). */
    supported: boolean;
    /** Pending deliveries that a worker could claim right now (partition rules applied). */
    claimable: number;
    /** Deliveries currently leased by a worker. */
    inFlight: number;
    /** claimable + inFlight — the value a scheduler should scale on. */
    total: number;
    /** True when either count hit its cap of 1000: the real backlog is at least this large. */
    capped: boolean;
}
'
SET
  @OutputTypeIsArray_3896f90effd3 = 0
SET
  @ExecutionMode_3896f90effd3 = N'Sync'
SET
